const $=s=>document.querySelector(s);
export const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const h=html,forms=['图像','视频','声音','文字','互动','3D'],modes=['共同创作','有偿委托','先交流再确定'],rights=['未说明，使用前请联系作者','仅供欣赏','可交流授权'];
let unsavedLocal=false,listingOffset=0,listingKey='';
let editorCleanup,communityCleanup;
let S,filter='全部',search='',sort='精选',reply=null,editor,profileDraft,navVersion=0,activeAudio,returnTo='works';
const listPositions={},draftTimers=new Map(),draftPending=new Map(),draftInFlight=new Map();
const uid=()=>crypto.randomUUID(),user=id=>S.users[id]||{id,name:'用户暂不可用',initial:'?',directions:[],collaboration:[],deliverables:[]},me=()=>user(S.viewer),work=id=>S.works.find(w=>w.id===id);
const route=()=>{const [p,q='']=(location.hash.slice(2)||'works').split('?');const [page,id]=p.split('/');return {page,id,q:new URLSearchParams(q)}};
const go=p=>{if(location.hash==='#/'+p)render();else location.hash='#/'+p};
const avatar=(u,size='')=>u.avatar?`<img class="avatar ${size}" src="${h(u.avatar)}" alt="">`:`<span class="avatar ${size}" aria-hidden="true">${h(u.initial)}</span>`;
const para=s=>h(s).replace(/\n/g,'<br>');
const communityContext=()=>({S,h,avatar,user,work,quote,tags,icon,readDraft,queueDraft,clearDraft,flushAll,commit,api,bindForm,render,toast,header,dialog,moreContent,state:()=>S,reply:()=>reply,setReply:v=>reply=v});
const tags=items=>`<div class="tags">${(items||[]).map(t=>`<span>${h(t)}</span>`).join('')}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
async function api(path,data,raw=false){if(path==='upload'&&raw&&S?.uploadMode==='signed'){const ticket=await api('upload/prepare',{name:data.name,mime:data.type,size:data.size});let result;try{result=await fetch(ticket.uploadUrl,{method:'PUT',headers:{'Content-Type':data.type,'x-upsert':'false'},body:data,credentials:'omit'})}catch{throw Error('图片上传中断，请重试。')}if(!result.ok)throw Error('图片没有上传成功，请重试。');return api('upload/complete',{id:ticket.id})}const options={credentials:'same-origin',headers:{}};if(data!==undefined){options.method='POST';options.headers['X-CSRF-Token']=S?.csrf||'';options.headers['Content-Type']=raw?data.type:'application/json';if(raw)options.headers['X-File-Name']=encodeURIComponent(data.name);options.body=raw?data:JSON.stringify(data)}let r;try{r=await fetch('/api/'+path,options)}catch{throw Error('连接中断，内容仍保留。请恢复连接后重试。')}let result;try{result=await r.json()}catch{throw Error('服务器暂时没有正确回应，请重试。')}if(!r.ok){const err=Error(result.error||'这次操作没有成功。');err.status=r.status;if(r.status===401&&!path.startsWith('auth/')){returnTo=location.hash.slice(2)||'works';let notice=document.querySelector('#session-notice');if(!notice){notice=document.createElement('div');notice.id='session-notice';notice.className='session-notice';document.querySelector('#main').before(notice)}notice.innerHTML='登录已失效，编辑内容仍保存在本机。<a href="#/auth">重新登录后继续 →</a>'}throw err}return result}
function stateQuery(){
 const r=route(),q=new URLSearchParams({view:r.page});
 if(['works','tutorials'].includes(r.page)){
  const personal=r.q.has('saved')?'saved':r.q.has('likes')?'likes':'';
  if(personal)q.set('personal',personal);else q.set('kind',r.page==='tutorials'?'教程与经验':'作品');
  q.set('sort',sort);if(search)q.set('query',search);if(filter!=='全部')q.set('form',filter);if(r.q.get('theme'))q.set('theme',r.q.get('theme'));
 }
 if(['creator','profile-edit','studio'].includes(r.page))q.set('author',r.id||'self');
 if(r.page==='studio'&&r.q.get('tab')==='trash')q.set('trash','1');
 if(['work','edit'].includes(r.page))q.set('id',r.id||'');
 if(r.page==='messages'){q.set('peer',r.id||'');if(r.q.get('work'))q.set('quote',r.q.get('work'))}
 return q;
}
async function refresh(){
 const q=stateQuery(),key=q.toString();
 if(key!==listingKey){listingKey=key;listingOffset=0}
 q.set('offset',listingOffset);const next=await api('state?'+q);
 if(key!==stateQuery().toString())return false;
 if(listingOffset&&S?.viewer===next.viewer){
  const cache=new Map(S.works.map(w=>[w.id,w]));for(const w of next.works)cache.set(w.id,w);
  next.works=[...cache.values()];next.ownerStats={...S.ownerStats,...next.ownerStats};const trash=new Map(S.deletedWorks.map(w=>[w.id,w]));for(const w of next.deletedWorks)trash.set(w.id,w);next.deletedWorks=[...trash.values()];next.page.ids=[...new Set([...(S.page?.ids||[]),...next.page.ids])];
 }
 // Older conversation pages are retained across polling and replies.
 if(S?.viewer===next.viewer)for(const th of next.threads){const old=S.threads.find(t=>t.key===th.key);if(old?.loadedOlder){const cache=new Map(old.messages.map(m=>[m.id,m]));for(const m of th.messages)cache.set(m.id,m);th.messages=[...cache.values()].sort((a,b)=>a.time-b.time||a.id.localeCompare(b.id));th.loadedOlder=true;th.hasOlder=old.hasOlder}}
 S=next;document.querySelector('#session-notice')?.remove();header();updatePersonalInsights();return true;
}
const moreContent=()=>S.page?.hasMore?'<div class="load-more"><button class="button light" data-action="load-more">查看更多内容</button><small>已显示 '+S.page.ids.length+' / '+S.page.total+' 件</small></div>':'';

async function commit(path,data){const out=await api(path,data);listingOffset=0;listingKey='';try{await refresh()}catch{toast('内容已保存，但页面更新暂时失败。请恢复连接后刷新。')}return out}
function needLogin(){if(S.viewer)return false;returnTo=location.hash.slice(2)||'works';go('auth');return true}
function localKey(key){return 'huanchang-draft:'+S.viewer+':'+key}
function readDraft(key){try{const d=JSON.parse(localStorage.getItem(localKey(key))||'null');if(d)return d}catch{}return S.drafts[key]||null}
function queueDraft(key,data){S.drafts[key]=data;try{localStorage.setItem(localKey(key),JSON.stringify(data));unsavedLocal=false}catch{unsavedLocal=true;toast('浏览器草稿空间不足，请先保存到服务器。')}draftPending.set(key,{actor:S.viewer,data:structuredClone(data)});clearTimeout(draftTimers.get(key));draftTimers.set(key,setTimeout(()=>flushDraft(key),650))}
async function flushDraft(key){
 if(draftInFlight.has(key))await draftInFlight.get(key);
 const p=draftPending.get(key);if(!p||p.actor!==S.viewer)return;
 draftPending.delete(key);
 const job=(async()=>{try{await api('draft',{key,data:p.data});const status=$('.draft-status');if(status)status.textContent='草稿已保存，可以稍后继续。'}catch(err){if(!draftPending.has(key))draftPending.set(key,p);const status=$('.draft-status');if(status)status.textContent=err.status===401?'登录已失效，草稿保留在本机。重新登录后继续。':'草稿暂存于本机，联网后可以重试。'}})();
 draftInFlight.set(key,job);await job;draftInFlight.delete(key);
}
async function flushAll(){await Promise.all([...new Set([...draftPending.keys(),...draftInFlight.keys()])].map(flushDraft))}
function clearDraft(key){clearTimeout(draftTimers.get(key));draftPending.delete(key);try{localStorage.removeItem(localKey(key))}catch{}delete S.drafts[key]}
function dialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${h(title)}</h2><button class="quiet" data-action="close-dialog" aria-label="关闭窗口">关闭</button></div>${body}`;if(!d.open)d.showModal();d.querySelector('input,textarea,button')?.focus()}
function error(form,err){let el=form?.querySelector('.form-error');if(el){el.textContent=err.message;el.scrollIntoView({block:'nearest'})}else toast(err.message)}
function messageUnreadCount(){return S.threads.filter(t=>!t.blocked&&((t.unread??t.messages.filter(m=>!m.seen).length)>0||S.notifications.some(n=>!n.seen&&n.kind==='message'&&n.target===(t.a===S.viewer?t.b:t.a)))).length}
function privateCount(kind){return S.privateCounts?.[kind]??S.works.filter(w=>S[kind].includes(w.id)).length}
function personalLink(url,symbol,label,count){return `<a href="#/${url}">${symbol?icon(symbol):''}<span>${label}</span><small data-personal-count="${url}" ${count?'':'hidden'}>${count}</small></a>`}
function personalMessages(){const unread=S.notifications.filter(n=>!n.seen&&n.kind!=='message').length;return `<nav class="profile-inbox-links" aria-label="我的交流">${personalLink('notifications','bell','消息动态',unread)}${personalLink('messages','message','私信',messageUnreadCount())}</nav>`}
function personalLibrary(count){return `<div class="profile-library-heading"><nav class="profile-library-tabs" aria-label="我的作品与收藏"><a class="is-current" href="#/creator/${S.viewer}?section=works" aria-current="page"><span>我的作品</span><small>${count}</small></a>${personalLink('works?saved','','收藏作品',privateCount('saved'))}${personalLink('works?likes','','赞过作品',privateCount('likes'))}</nav><details class="profile-stats-guide"><summary>数据说明</summary><p>点赞与收藏按当前有效记录统计，不公开收藏者身份。浏览从本次更新开始记录，不计作者本人，同一浏览者30分钟内重复打开只计一次。数据仅你可见。</p></details></div>`}

function workStats(w){const v=S.ownerStats?.[w.id]||{views:0,likes:0,saved:0};return `<div class="profile-work-stats" data-work="${h(w.id)}" aria-label="作品数据"><span>${v.views} 浏览</span><span>${v.likes} 点赞</span><span>${v.saved} 收藏</span></div>`}
function updatePersonalInsights(){if(route().page!=='creator'||route().id!==S.viewer)return;for(const node of document.querySelectorAll('.profile-work-stats[data-work]')){const v=S.ownerStats?.[node.dataset.work];if(v)[...node.children].forEach((el,i)=>el.textContent=[v.views+' 浏览',v.likes+' 点赞',v.saved+' 收藏'][i])}const counts={'works?saved':privateCount('saved'),'works?likes':privateCount('likes'),notifications:S.notifications.filter(n=>!n.seen&&n.kind!=='message').length,messages:messageUnreadCount()};for(const node of document.querySelectorAll('[data-personal-count]')){node.textContent=counts[node.dataset.personalCount];node.hidden=!counts[node.dataset.personalCount]}}
const viewRecords=new Map();function recordWorkView(id){const key=(S.viewer||'visitor')+':'+id;if(viewRecords.get(key)>Date.now()-30*60000)return;viewRecords.set(key,Date.now());api('view',{id}).catch(()=>viewRecords.delete(key))}
function header(){
 const r=route(),unread=S.notifications.filter(n=>!n.seen&&n.kind!=='message').length,messageUnread=messageUnreadCount(),current=['work','edit'].includes(r.page)?(work(r.id)?.kind==='教程与经验'?'tutorials':'works'):r.page==='creator'?'creators':r.page;
 $('#header').innerHTML=`<div class="header-inner hc-header"><a class="brand hc-brand" href="#/works" aria-label="幻场首页"><img src="brand.svg" alt=""><span><strong>幻场</strong><small>HUANCHANG</small></span></a><nav aria-label="主导航">${[['works','作品'],['tutorials','教程与经验'],['creators','创作者']].map(([p,l])=>`<a href="#/${p}" ${current===p?'aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="header-right"><a class="message-link" href="#/notifications">动态${unread?`<span class="unread">${unread}</span>`:''}</a><a class="message-link" href="#/messages">消息${messageUnread?`<span class="unread">${messageUnread}</span>`:''}</a><a class="button lime publish-trigger" href="#/publish">${icon('plus')}<span>发布</span></a>${S.viewer?`<button class="identity" data-action="account" aria-label="个人菜单">${avatar(me())}<span>${h(me().name)}</span></button>`:'<a class="login-link" href="#/auth">登录</a>'}</div></div>${S.demoEnabled?'<div class="dev-note">本机预览 · 示例内容已标示 <button data-action="demo-menu">切换体验身份</button></div>':''}`;
}
