function notifications(){if(needLogin())return;mountNotifications(communityContext())}
function authPage(q){const mode=q.get('mode')||'login';if(mode==='email'){mountEmailRecovery(communityContext(),async out=>{await refresh();go(returnTo);dialog('请保存新的恢复码',`<p>密码已更新，旧登录与旧恢复码已失效。</p><code class="recovery-code">${h(out.recoveryCode)}</code><button class="button dark" data-action="close-dialog">我已保存</button>`)});return}$('#main').innerHTML=`<div class="container auth-page"><p class="eyebrow">幻场 / 让创造者与想象相遇</p><h1>${mode==='register'?'从这里开始。':mode==='recover'?'恢复你的账户。':'欢迎回来。'}</h1><p class="muted">浏览无需登录，登录后可以发布、收藏与交流。</p><form id="auth-form" class="auth-form">${mode==='register'?field('name','显示名称','',24,'你希望大家怎样称呼你'):''}<label>账号名<input name="handle" autocomplete="username" pattern="[a-z][a-z0-9_]{2,31}" maxlength="32" required placeholder="3–32 位小写字母、数字、下划线"></label>${mode==='register'?'<label>邮箱 <span class="muted">（选填）</span><input name="email" type="email" autocomplete="email" maxlength="254" placeholder="name@example.com" aria-describedby="registration-email-help"></label><p id="registration-email-help" class="field-help">'+(S.mailEnabled?'仅自己可见。注册后可在账户设置验证，用于邮件找回。':'仅自己可见。试用期间暂不启用邮件找回，请保存账户恢复码。')+'</p>':''}${mode==='recover'?'<label>账户恢复码<input name="code" autocomplete="off" required placeholder="注册时保存的恢复码"></label>':''}<label>${mode==='recover'?'新密码':'密码'}<input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="${mode==='login'?1:10}" maxlength="128" required placeholder="${mode==='login'?'你的密码':'至少 10 位'}"></label>${mode==='register'||mode==='recover'?'<p class="field-help">'+(S.mailEnabled?'请保存账户恢复码。邮箱验证后，也可以通过邮件找回。':'请保存账户恢复码。试用期间，忘记密码需使用恢复码找回。')+'</p>':''}${mode==='register'?'<p class="field-help">注册资料用于账户与社区功能。<a href="#/guidelines">社区规则</a> · <a href="#/privacy">隐私说明</a></p>':''}<button class="button dark">${mode==='register'?'创建账户':mode==='recover'?'重设密码':'登录'}</button><p class="form-error" role="alert"></p></form><div class="auth-links"><a href="#/auth?mode=${mode==='register'?'login':'register'}">${mode==='register'?'已有账户，登录':'创建账户'}</a><a href="#/auth?mode=recover">使用恢复码找回</a>${S.mailEnabled?'<a href="#/auth?mode=email">通过邮箱找回</a>':''}</div>${S.demoEnabled?'<button class="quiet" data-action="demo-menu">先用示例身份体验</button>':''}</div>`;bindForm('#auth-form',async f=>{await flushAll();const data=Object.fromEntries(new FormData(f)),out=await api('auth/'+mode,data);await refresh();go(returnTo);if(out.recoveryCode)dialog('请保存你的账户恢复码',`<p>这是找回账户的凭据，只在这里展示。请保存在自己的密码管理器中。</p><code class="recovery-code">${h(out.recoveryCode)}</code><p class="field-help">${S.mailEnabled?'验证邮箱后也可通过邮件找回；':'试用期间暂不启用邮件找回；'}重设密码后旧恢复码失效。</p><button class="button dark" data-action="close-dialog">我已保存，继续</button>`);else toast('登录成功。')})}
async function adminPage(){if(needLogin())return;if(!S.admin){$('#main').innerHTML=empty('这里需要管理员权限','内容管理入口只向维护人员开放。');return}try{const A=await api('admin');$('#main').innerHTML=`<div class="container admin-page"><p class="eyebrow">内容维护</p><h1>管理与处理</h1><section><h2>举报队列</h2>${A.reports.map(r=>`<article class="manage-row"><div><h3>举报：${{work:'作品',comment:'讨论',user:'用户',message:'私信'}[r.kind]}</h3><p>${h(r.reason)}</p><p class="muted">${h(r.evidence||'')} · ${r.status==='pending'?'待处理':'已处理：'+h(r.resolution)}</p></div>${r.status==='pending'?`<button class="button light" data-action="resolve-report" data-id="${r.id}" data-kind="${r.kind}">处理</button>`:''}</article>`).join('')||'<p class="muted">没有举报。</p>'}</section><section><h2>精选与内容状态</h2><p class="muted">精选理由描述作品值得看的具体内容，不作为能力认证。</p>${A.works.map(w=>`<article class="manage-row"><div><h3>${h(w.title)}</h3><p>${h(w.curatedReason||'尚未精选')}${w.hidden?' · 已下架':''}${w.deleted?' · 作者已移除':''}</p></div><div class="action-row"><button class="button light" data-action="curate" data-id="${w.id}" data-reason="${h(w.curatedReason)}">编辑精选理由</button>${w.hidden?`<button class="button light" data-action="admin-restore-work" data-id="${w.id}">恢复展示</button>`:''}</div></article>`).join('')}</section><section><h2>账户状态</h2>${A.users.map(u=>`<article class="manage-row"><div>${h(u.name)} · ${u.disabled?'已停用':'正常'}${u.demo?' · 示例':''}</div>${u.disabled?`<button class="button light" data-action="admin-restore-user" data-id="${u.id}">恢复账户</button>`:''}</article>`).join('')}</section></div>`}catch(e){toast(e.message)}}
function settings(){if(needLogin())return;mountSettings(communityContext())}
function about(){$('#main').innerHTML=`<div class="container about-page"><p class="eyebrow">幻场 HUANCHANG</p><h1>让想象被看见，<br>让创造者被找到。</h1><p class="lead">这里是分享 AI 创作、理解创作过程、认识彼此的地方。</p><div class="about-grid"><section><h2>作品，是认识的起点</h2><p>图片、视频、声音、文字、互动与 3D，都可以表达一个想法。角色与故事也可以跨越这些形式。</p></section><section><h2>过程，让能力更清楚</h2><p>分享自己的贡献、AI 如何参与，以及值得保留的判断。工具名和漂亮的画面之外，我们也关心创造者做了什么。</p></section><section><h2>交流，带着具体来处</h2><p>围绕作品讨论，把感兴趣的作品带入私信。合作偏好帮助双方找到沟通方向，是否合作由双方自行决定。</p></section><section><h2>尊重作者与边界</h2><p>收藏不代表授权。未经作者允许，请勿把展示内容用于再发布或商业用途。遇到问题可以举报；不想继续交流时可以屏蔽。</p></section></div><p class="media-note">当前是本机运行的建设版本。示例内容明确标示；没有支付、订单或平台担保。账户及你提交的内容保存在本机服务中，尚未发布公网。</p><div class="action-row"><a class="button dark" href="#/works">开始看作品</a><a class="text-link" href="#/guidelines">社区规则 →</a><a class="text-link" href="#/privacy">隐私说明 →</a></div></div>`}
let rendered='';
function render(scroll=true){if(!S)return;editorCleanup?.();editorCleanup=null;communityCleanup?.();communityCleanup=null;disposeHomeMotion();disposeWall();const r=route(),old=rendered;document.body.classList.toggle('is-messages',r.page==='messages'&&!!S.viewer);activeAudio?.pause();if(scroll&&old)listPositions[old]=scrollY;header();document.title='幻场 · '+(r.page==='works'&&!r.q.has('saved')&&!r.q.has('likes')&&!r.q.has('theme')?'让想象成形，让彼此相遇':r.page==='work'?work(r.id)?.title||'作品':({works:'作品',tutorials:'教程与经验',creators:'创作者',messages:'消息',studio:'我的内容','profile-edit':'编辑主页',publish:'分享创作',edit:'编辑内容',notifications:'动态',settings:'账户与交流设置',auth:'账户',about:'关于幻场'}[r.page]||'创造者与想象'));if(['works','tutorials'].includes(r.page))gallery();else if(r.page==='work')workPage(r.id);else if(r.page==='creator')profilePage(r.id);else if(r.page==='creators')creators();else if(r.page==='publish'||r.page==='edit')editorPage(r.page==='edit'?r.id:null,r.q);else if(r.page==='profile-edit')profileEditor();else if(r.page==='studio')studio(r.q);else if(r.page==='messages')messages(r.id,r.q);else if(r.page==='notifications')notifications();else if(r.page==='auth')authPage(r.q);else if(r.page==='settings')settings();else if(r.page==='admin')adminPage();else if(r.page==='about')about();else if(['privacy','guidelines'].includes(r.page))mountSiteInfo(communityContext(),r.page);else $('#main').innerHTML=empty('这里暂时无法查看','请回到作品继续浏览。');rendered=location.hash||'#/works';if(scroll){$('#main').focus({preventScroll:true});const scrollRoute=location.hash;requestAnimationFrame(()=>{if(location.hash!==scrollRoute)return;window.scrollTo(0,['works','tutorials','creators'].includes(r.page)?listPositions[rendered]||0:0);if(r.page==='work'){const cid=r.q.get('comment');if(cid){if(!focusComment(cid)){$('#discussion')?.scrollIntoView();toast('这条评论暂时不可见，已定位到讨论区。')}}else if(r.q.has('discussion'))$('#discussion')?.scrollIntoView()}if(r.page==='creator'&&r.q.get('section')==='works')$('#creator-works')?.scrollIntoView()})}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(b.disabled||b.dataset.busy)return;try{
if(a==='load-more'){b.disabled=true;try{listingOffset=S.page.nextOffset;await refresh();render(false)}catch(err){toast(err.message)}finally{if(b.isConnected)b.disabled=false}return}
if(a==='jump-section'){const target=document.getElementById(b.dataset.target);target?.scrollIntoView({block:'start'});return}
if(a==='close-dialog'){$('#dialog').close();return}
if(a==='retry'){await refresh();render();return}
if(a==='account'){dialog('我的幻场',`<a class="account-entry" href="#/creator/${S.viewer}" data-action="close-dialog">我的主页 →</a><a class="account-entry" href="#/studio" data-action="close-dialog">作品与草稿 →</a><a class="account-entry" href="#/works?saved" data-action="close-dialog">我的收藏 →</a><a class="account-entry" href="#/works?likes" data-action="close-dialog">我赞过的作品 →</a><a class="account-entry" href="#/notifications" data-action="close-dialog">消息动态 →</a><a class="account-entry" href="#/messages" data-action="close-dialog">私信 →</a><a class="account-entry" href="#/settings" data-action="close-dialog">账户与交流设置 →</a>${S.admin?'<a class="account-entry" href="#/admin" data-action="close-dialog">内容管理 →</a>':''}<button class="quiet" data-action="logout">退出登录</button>`);return}
if(a==='demo-menu'){dialog('双角色体验',`<p class="muted">示例作者不会自动回复。建议用林间与青禾两个示例身份：发送评论或私信 → 切换到对方查看并回复 → 切回发送方查看结果。此入口仅用于本机体验。</p>${S.viewer&&!me().demo?'<p class="field-help">当前是你的真实账户。进入示例身份后，需要重新登录才能回到你的账户；已有内容和消息会保留。</p>':''}<div class="accounts">${Object.values(S.users).filter(u=>u.demo).map(u=>`<button data-action="demo" data-id="${u.id}">${avatar(u)}<strong>${h(u.name)}</strong><span>进入 →</span></button>`).join('')}</div>`);return}
if(a==='demo'){const previous=S.viewer,where=route();await flushAll();await api('auth/demo',{id:b.dataset.id});await refresh();$('#dialog').close();go(where.page==='messages'&&previous&&previous!==S.viewer?'messages/'+previous:where.page==='work'?'work/'+where.id:'works');render();toast('已进入示例身份：'+me().name);return}
if(a==='logout'){await flushAll();await api('auth/logout',{});await refresh();$('#dialog').close();go('works');render();toast('已退出登录。');return}
if(a==='filter'){filter=b.dataset.value;await refresh();gallery();$(`[data-action=filter][data-value="${filter}"]`)?.focus({preventScroll:true});return}
if(a==='sort'){sort=b.dataset.value;await refresh();gallery();$(`[data-action=sort][data-value="${sort}"]`)?.focus({preventScroll:true});return}
if(a==='reset-search'){search='';filter='全部';await refresh();gallery();$('#search')?.focus({preventScroll:true});return}
if(a==='contact'){if(user(b.dataset.peer).demo&&!S.demoEnabled){toast('此作者为展示样例，不接收私信。可以在创作者页寻找真实用户。');return}if(needLogin())return;go('messages/'+b.dataset.peer+(b.dataset.work?'?work='+b.dataset.work:''));return}
if(a==='image'){showWorkImage({h,dialog},b.dataset.src);return}
if(a==='share'){try{await navigator.clipboard.writeText(location.href);toast('链接已复制。当前链接只能在运行这项服务的电脑上打开。')}catch{dialog('分享作品',`<p>复制下面的地址：</p><input readonly value="${h(location.href)}"><p class="field-help">当前为本机链接。</p>`)}return}
if(a==='discussion'){$('#discussion')?.scrollIntoView();$('.discussion-compose')?.setAttribute('open','');$('#comment-input')?.focus({preventScroll:true});return}
if(a==='reply'){if(needLogin())return;reply=S.comments.find(c=>c.id===b.dataset.id);render(false);$('#reply-form')?.scrollIntoView({block:'center'});$('#reply-input')?.focus({preventScroll:true});return}
if(a==='cancel-reply'){const id=reply?.id;reply=null;render(false);$(`#comment-${id} [data-action=reply]`)?.focus({preventScroll:true});return}
if(a==='remove-quote'){const key='message:'+route().id,d=readDraft(key)||{body:'',work:null};d.work=null;queueDraft(key,d);render(false);return}
if(a==='latest-work'){const key='publish:'+uid(),copy={...editor,title:(editor.title.slice(0,52)+' · 草稿副本'),id:uid(),revision:undefined,key};await api('draft',{key,data:copy});clearDraft(editor.key);await api('draft',{key:editor.key,data:null});await refresh();render(false);toast('旧草稿已保留在我的内容中。');return}
if(a==='profile-backup'){let copy;try{copy=JSON.parse(localStorage.getItem('huanchang-profile-conflict:'+S.viewer)||'null')}catch{}if(!copy){toast('当前没有因版本冲突保留的旧修改。');return}dialog('保留的旧修改',`<p class="muted">可复制需要的部分，核对后补充到最新资料。</p><textarea readonly rows="12">${h(['名称：'+copy.name,'一句话介绍：'+copy.bio,'关于我：'+copy.intro,'所在地：'+copy.location,'创作方向：'+copy.directions.join('、'),'可做内容：'+copy.deliverables.join('、'),'合作方式：'+copy.collaboration.join('、')].join('\n\n'))}</textarea>`);return}
if(a==='latest-profile'){try{localStorage.setItem('huanchang-profile-conflict:'+S.viewer,JSON.stringify(profileDraft))}catch{throw Error('本机副本未保存，请先复制修改内容。')}clearDraft('profile');await commit('draft',{key:'profile',data:null});render(false);toast('已读取最新资料，旧修改保留为本机副本。');return}
if(a==='confirm-delete-draft'){dialog('删除这份草稿？',`<p>删除后无法恢复，已发布的作品不会改变。</p><div class="action-row"><button class="button light" data-action="close-dialog">保留草稿</button><button class="button dark" data-action="delete-draft" data-key="${h(b.dataset.key)}">确认删除草稿</button></div>`);return}
if(a==='block'&&b.dataset.enabled==='true'){dialog('屏蔽这位用户？',`<p>对方的作品会从你的浏览中隐藏，双方不能新增私信。已有消息记录保留，可在账户设置中解除。</p><div class="action-row"><button class="button light" data-action="close-dialog">暂不屏蔽</button><button class="button dark" data-action="block-confirmed" data-peer="${h(b.dataset.peer)}" data-enabled="true">确认屏蔽</button></div>`);return}
if(a==='report'){if(needLogin())return;dialog('举报'+({work:'作品',comment:'讨论',user:'用户',message:'消息'}[b.dataset.kind]||'内容'),`<form id="report-form"><label>问题类型<select name="category"><option>垃圾信息或骚扰</option><option>冒用或侵权线索</option><option>不当内容</option><option>其他问题</option></select></label><label>请说明问题<textarea name="reason" maxlength="480" required placeholder="指出具体问题，方便维护者判断。"></textarea></label><p class="field-help">举报内容仅供维护者处理，不公开给被举报者。</p><button class="button dark">提交举报</button><p class="form-error" role="alert"></p></form>`);bindForm('#report-form',async f=>{await commit('report',{kind:b.dataset.kind,target:b.dataset.id,reason:f.elements.category.value+'：'+f.elements.reason.value});$('#dialog').close();toast('举报已提交，处理结果会出现在动态中。')});return}
if(a==='curate'){dialog('编辑精选理由',`<form id="curate-form"><label>具体看点<textarea name="reason" maxlength="250">${h(b.dataset.reason)}</textarea></label><p class="field-help">清空即可取消精选。</p><button class="button dark">保存</button><p class="form-error" role="alert"></p></form>`);bindForm('#curate-form',async f=>{await commit('admin-action',{action:'curate',id:b.dataset.id,reason:f.elements.reason.value});$('#dialog').close();render(false)});return}
if(a==='resolve-report'){dialog('处理举报',`<form id="resolve-form"><label>处理结果<select name="decision"><option value="dismiss">保留内容</option>${b.dataset.kind==='message'?'':'<option value="hide">下架内容／停用被举报账户</option>'}</select></label><p class="field-help">私信举报请调查后说明处理结果，此处保留对话记录。</p><label>处理说明<textarea name="note" required maxlength="500"></textarea></label><button class="button dark">提交处理结果</button><p class="form-error" role="alert"></p></form>`);bindForm('#resolve-form',async f=>{await commit('admin-action',{action:'resolve',id:b.dataset.id,...Object.fromEntries(new FormData(f))});$('#dialog').close();render(false)});return}
if(needLogin())return;b.dataset.busy='1';b.disabled=true;
if(a==='reaction'){const kind=b.dataset.kind;await commit('reaction',{id:b.dataset.id,kind,enabled:!S[kind].includes(b.dataset.id)});render(false)}
else if(a==='delete-comment'||a==='pin-comment'){await commit('comment-action',{id:b.dataset.id,action:a==='delete-comment'?'delete':'pin'});render(false);toast(a==='delete-comment'?'讨论已删除，其他人的回复保留。':'置顶状态已更新。')}
else if(a==='thread-action'){await commit('thread-action',{id:b.dataset.id,action:b.dataset.value});render(false)}
else if(a==='delete-work'||a==='restore-work'){await commit('work-status',{id:b.dataset.id,action:a==='delete-work'?'delete':'restore'});render(false);toast(a==='delete-work'?'已移除，可以在“已移除”中恢复。':'内容已恢复。')}
else if(a==='delete-draft'){const key=b.dataset.key;await flushDraft(key);await commit('draft',{key,data:null});clearDraft(key);$('#dialog').close();render(false);toast('草稿已删除。')}
else if(a==='block'||a==='block-confirmed'){await commit('block',{peer:b.dataset.peer,enabled:b.dataset.enabled==='true'});$('#dialog').close();render(false);toast(b.dataset.enabled==='true'?'已屏蔽，新增交流将被阻止。':'已取消屏蔽。')}
else if(a==='read-all'){await commit('notifications',{});render(false)}
else if(a==='open-notification'){await commit('notifications',{id:b.dataset.id});go(b.dataset.kind==='message'?'messages/'+b.dataset.target:'work/'+b.dataset.target+(b.dataset.comment?'?comment='+encodeURIComponent(b.dataset.comment):'?discussion=1'))}
else if(a.startsWith('admin-restore')){await commit('admin-action',{action:a==='admin-restore-work'?'restore-work':'restore-user',id:b.dataset.id});render(false)}
else if(a==='retry'){await refresh();render()}
}catch(err){toast(err.message)}finally{if(b.isConnected){delete b.dataset.busy;b.disabled=false}}});
window.addEventListener('hashchange',async()=>{flushAll();reply=null;listingOffset=0;listingKey='';if(['works','tutorials'].includes(route().page)){search='';filter='全部';sort=route().q.has('saved')||route().q.has('likes')?'最新':'精选'}try{if(await refresh())render()}catch(err){toast(err.message)}});
window.addEventListener('online',()=>{flushAll();toast('连接已恢复，可以继续保存。')});
window.addEventListener('beforeunload',e=>{flushAll();if(unsavedLocal||document.querySelector('form[data-uploading]')){e.preventDefault();e.returnValue=''}});
setInterval(async()=>{if(!S||document.visibilityState!=='visible'||$('#dialog').open)return;try{const old=S,previousActor=S.viewer,oldThread=old.threads.find(t=>[t.a,t.b].includes(route().id));await refresh();if(draftPending.size)flushAll();if(previousActor!==S.viewer){toast(S.viewer?'登录身份已变化，请确认后继续。':'登录已失效，草稿已保留。请重新登录。');render(false);return}if(route().page==='messages'&&route().id){const next=S.threads.find(t=>[t.a,t.b].includes(route().id));if(JSON.stringify(oldThread)!==JSON.stringify(next)){const ta=$('#message-input'),selection=ta?[ta.selectionStart,ta.selectionEnd]:null,focused=document.activeElement===ta;render(false);if(focused&&$('#message-input')){$('#message-input').focus({preventScroll:true});$('#message-input').setSelectionRange(...selection)}}}}catch{}},12000);
try{await refresh();render()}catch(err){$('#main').innerHTML=`<div class="container empty"><h1>暂时没能打开幻场</h1><p>${h(err.message)}</p><button class="button dark" data-action="retry">重新连接</button></div>`}
